package pe.edu.upeu.notificacion.exception; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*; @RestControllerAdvice public class GlobalExceptionHandler{@ExceptionHandler(ResourceNotFoundException.class)ResponseEntity<?>nf(ResourceNotFoundException e){return ResponseEntity.status(404).body(Map.of("message",e.getMessage()));}@ExceptionHandler({IllegalArgumentException.class,IllegalStateException.class})ResponseEntity<?>bad(RuntimeException e){return ResponseEntity.badRequest().body(Map.of("message",e.getMessage()));}}